    :param paths: the list pf paths to search (relative to self.path)
    :param exclude: the list of path to exclude
    :param extensions: the list of allowed extensions (if False, all
        extensions are allowed)
    """
    if exclude is None:
        exclude = []
    # backward compatibility for older generators
    if isinstance(paths, str):
        paths = [paths]

    # group the exclude dir names by parent path, for use with walk()
    exclusions_by_dirpath = {}
    for e in exclude:
        if not e or _ends_with_separator(e):
            # The final component of such a path is empty, so it never
            # names a directory to exclude.
            continue
        excluded = Path(self.path, e)
        exclusions_by_dirpath.setdefault(excluded.parent, set()).add(excluded.name)

    files = set()
    ignores = self.settings["IGNORE_FILES"]
    for path in paths:
        root = Path(self.path, path)

        if root.is_dir():
            for dirpath, dirs, temp_files in walk(root, followlinks=True):
                if dirpath == root and _ends_with_separator(path or self.path):
                    # Walking a path spelled with a trailing separator
                    # never matched exclusions in its top directory.
                    excl = ()
                else:
                    excl = exclusions_by_dirpath.get(dirpath, ())
                # We copy the `dirs` list as we will modify it in the loop:
                for d in list(dirs):
                    if d in excl or any(
                        fnmatch.fnmatch(d, ignore) for ignore in ignores
                    ):
                        if d in dirs:
                            dirs.remove(d)

                reldir = relative_path(dirpath, self.path)
                for f in temp_files:
                    fp = str(reldir / f)
                    if self._include_path(fp, extensions):
                        files.add(fp)
        elif root.exists() and self._include_path(path, extensions):
            files.add(path)  # can't walk non-directories
    return files

